@import url('https://fonts.googleapis.com/css2?family=Nunito:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Skeuomorphism — brushed metal, linen, glossy bevels, inset engravings */
.theme-skeuomorphism {
  --bg: oklch(0.82 0.012 250);
  --surface: oklch(0.93 0.008 250);
  --surface-2: oklch(0.87 0.01 250);
  --fg: oklch(0.28 0.015 250);
  --fg-muted: oklch(0.5 0.015 250);
  --accent: oklch(0.55 0.14 245);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.6 0.13 145);
  --line: oklch(0.62 0.015 250);
  --success: oklch(0.6 0.14 148);
  --warning: oklch(0.78 0.14 82);
  --danger: oklch(0.56 0.19 25);

  --radius: 0.625rem;
  --radius-sm: 0.375rem;
  --radius-lg: 1rem;
  --radius-pill: 9999px;

  --shadow-1: inset 0 1px 0 oklch(1 0 0 / 85%), inset 0 -1px 0 oklch(0.4 0.01 250 / 25%),
    0 1px 3px oklch(0.3 0.01 250 / 40%);
  --shadow-2: inset 0 1px 0 oklch(1 0 0 / 90%), 0 6px 12px -3px oklch(0.3 0.01 250 / 45%);
  --shadow-3: inset 0 2px 0 oklch(1 0 0 / 90%), 0 16px 32px -10px oklch(0.28 0.01 250 / 55%);
  --glow: inset 0 2px 5px oklch(0.35 0.01 250 / 50%);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Nunito", "Inter", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.08em;

  background-color: var(--bg);
  background-image:
    repeating-linear-gradient(0deg, oklch(1 0 0 / 8%) 0 1px, transparent 1px 2px),
    repeating-linear-gradient(90deg, oklch(0.4 0.01 250 / 6%) 0 1px, transparent 1px 2px),
    linear-gradient(180deg, oklch(0.88 0.01 250), oklch(0.76 0.014 250));
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
  text-shadow: 0 1px 0 oklch(1 0 0 / 55%);
}

.theme-skeuomorphism h1,
.theme-skeuomorphism h2,
.theme-skeuomorphism h3 {
  font-family: var(--font-display);
  font-weight: 800;
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-skeuomorphism button { background-image: linear-gradient(180deg, oklch(1 0 0 / 35%), transparent 45%, oklch(0 0 0 / 8%)); box-shadow: inset 0 1px 0 oklch(1 0 0 / 70%), 0 1px 3px oklch(0 0 0 / 25%); }
.theme-skeuomorphism button:active { background-image: linear-gradient(180deg, oklch(0 0 0 / 10%), transparent); box-shadow: inset 0 2px 4px oklch(0 0 0 / 25%); }

/* depth */
.theme-skeuomorphism thead th { background-image: linear-gradient(180deg, oklch(0.96 0.008 250), oklch(0.86 0.01 250)); border-bottom: 1px solid var(--line); box-shadow: inset 0 1px 0 oklch(1 0 0 / 90%); color: var(--fg-muted); font-size: 0.72em; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; text-shadow: 0 1px 0 oklch(1 0 0 / 80%); }
.theme-skeuomorphism td { border-bottom: 1px solid oklch(0.74 0.012 250); box-shadow: 0 1px 0 oklch(1 0 0 / 60%); }
.theme-skeuomorphism tbody tr:nth-child(even) { background: oklch(0.9 0.008 250 / 50%); }
.theme-skeuomorphism tbody tr:hover { background: oklch(0.85 0.05 245 / 30%); }
.theme-skeuomorphism input, .theme-skeuomorphism textarea, .theme-skeuomorphism select { background: linear-gradient(180deg, oklch(0.9 0.008 250), oklch(0.97 0.006 250) 30%); border: 1px solid oklch(0.58 0.015 250); border-radius: var(--radius-sm); box-shadow: inset 0 2px 4px oklch(0.35 0.01 250 / 30%), 0 1px 0 oklch(1 0 0 / 80%); text-shadow: none; }
.theme-skeuomorphism input:focus-visible, .theme-skeuomorphism textarea:focus-visible, .theme-skeuomorphism select:focus-visible { outline: none; border-color: oklch(0.55 0.14 245); box-shadow: inset 0 2px 4px oklch(0.35 0.01 250 / 25%), 0 0 0 3px oklch(0.55 0.14 245 / 30%); }
.theme-skeuomorphism kbd { background: linear-gradient(180deg, oklch(0.97 0.006 250), oklch(0.85 0.01 250)); border: 1px solid oklch(0.55 0.012 250); border-bottom-width: 3px; border-radius: 0.35em; padding: 0.1em 0.5em; font-family: var(--font-mono); font-size: 0.85em; box-shadow: inset 0 1px 0 oklch(1 0 0 / 95%), 0 1px 2px oklch(0.3 0.01 250 / 35%); text-shadow: 0 1px 0 oklch(1 0 0 / 70%); }
.theme-skeuomorphism a { color: oklch(0.45 0.14 245); font-weight: 600; text-decoration: underline; text-decoration-color: oklch(0.45 0.14 245 / 45%); text-underline-offset: 0.18em; }
.theme-skeuomorphism a:hover { text-decoration-color: oklch(0.45 0.14 245); }
.theme-skeuomorphism ::selection { background: oklch(0.55 0.14 245 / 30%); text-shadow: none; }
.theme-skeuomorphism ::-webkit-scrollbar { width: 14px; height: 14px; }
.theme-skeuomorphism ::-webkit-scrollbar-track { background: linear-gradient(90deg, oklch(0.72 0.012 250), oklch(0.8 0.01 250)); box-shadow: inset 1px 0 3px oklch(0.35 0.01 250 / 40%); }
.theme-skeuomorphism ::-webkit-scrollbar-thumb { background: linear-gradient(90deg, oklch(0.95 0.006 250), oklch(0.78 0.01 250)); border: 1px solid oklch(0.55 0.012 250); border-radius: 7px; box-shadow: inset 0 1px 0 oklch(1 0 0 / 85%); }
.theme-skeuomorphism ::-webkit-scrollbar-thumb:hover { background: linear-gradient(90deg, oklch(0.97 0.006 250), oklch(0.82 0.01 250)); }
.theme-skeuomorphism .label-caps { color: var(--fg-muted); text-shadow: 0 1px 0 oklch(1 0 0 / 85%); }
.theme-skeuomorphism .themed-border { border-color: var(--line); box-shadow: inset 0 1px 0 oklch(1 0 0 / 85%), 0 1px 0 oklch(1 0 0 / 55%); }

/* alt mode: machined night — dark brushed aluminum, letterpress engraving */
.theme-skeuomorphism.alt-mode {
  --bg: oklch(0.3 0.01 250);
  --surface: oklch(0.38 0.01 250);
  --surface-2: oklch(0.34 0.01 250);
  --fg: oklch(0.93 0.005 250);
  --fg-muted: oklch(0.72 0.008 250);
  --accent: oklch(0.65 0.14 245);
  --accent-fg: oklch(0.15 0.02 245);
  --line: oklch(0.18 0.01 250);
  --shadow-1: inset 0 1px 0 oklch(1 0 0 / 14%), inset 0 -1px 0 oklch(0 0 0 / 35%), 0 1px 3px oklch(0 0 0 / 50%);
  --shadow-2: inset 0 1px 0 oklch(1 0 0 / 16%), 0 6px 12px -3px oklch(0 0 0 / 55%);
  --shadow-3: inset 0 2px 0 oklch(1 0 0 / 16%), 0 16px 32px -10px oklch(0 0 0 / 65%);
  --glow: inset 0 2px 5px oklch(0 0 0 / 60%);
  background-image:
    repeating-linear-gradient(0deg, oklch(1 0 0 / 4%) 0 1px, transparent 1px 2px),
    repeating-linear-gradient(90deg, oklch(0 0 0 / 8%) 0 1px, transparent 1px 2px),
    linear-gradient(180deg, oklch(0.34 0.01 250), oklch(0.24 0.01 250));
  text-shadow: 0 -1px 0 oklch(0 0 0 / 55%);
}
.theme-skeuomorphism.alt-mode button { background-image: linear-gradient(180deg, oklch(1 0 0 / 14%), transparent 45%, oklch(0 0 0 / 22%)); box-shadow: inset 0 1px 0 oklch(1 0 0 / 22%), 0 1px 3px oklch(0 0 0 / 45%); }
.theme-skeuomorphism.alt-mode button:active { background-image: linear-gradient(180deg, oklch(0 0 0 / 25%), transparent); box-shadow: inset 0 2px 4px oklch(0 0 0 / 55%); }
.theme-skeuomorphism.alt-mode thead th { background-image: linear-gradient(180deg, oklch(0.42 0.01 250), oklch(0.33 0.01 250)); box-shadow: inset 0 1px 0 oklch(1 0 0 / 14%); text-shadow: 0 -1px 0 oklch(0 0 0 / 55%); }
.theme-skeuomorphism.alt-mode td { border-bottom-color: oklch(0.22 0.01 250); box-shadow: 0 1px 0 oklch(1 0 0 / 8%); }
.theme-skeuomorphism.alt-mode tbody tr:nth-child(even) { background: oklch(0.33 0.01 250 / 60%); }
.theme-skeuomorphism.alt-mode tbody tr:hover { background: oklch(0.4 0.04 245 / 30%); }
.theme-skeuomorphism.alt-mode input, .theme-skeuomorphism.alt-mode textarea, .theme-skeuomorphism.alt-mode select { background: linear-gradient(180deg, oklch(0.24 0.01 250), oklch(0.3 0.01 250) 30%); border-color: oklch(0.16 0.01 250); color: var(--fg); box-shadow: inset 0 2px 4px oklch(0 0 0 / 45%), 0 1px 0 oklch(1 0 0 / 10%); }
.theme-skeuomorphism.alt-mode kbd { background: linear-gradient(180deg, oklch(0.42 0.01 250), oklch(0.3 0.01 250)); border-color: oklch(0.16 0.01 250); box-shadow: inset 0 1px 0 oklch(1 0 0 / 18%), 0 1px 2px oklch(0 0 0 / 50%); text-shadow: 0 -1px 0 oklch(0 0 0 / 60%); }
.theme-skeuomorphism.alt-mode a { color: oklch(0.72 0.13 240); text-decoration-color: oklch(0.72 0.13 240 / 45%); }
.theme-skeuomorphism.alt-mode ::-webkit-scrollbar-track { background: linear-gradient(90deg, oklch(0.2 0.01 250), oklch(0.26 0.01 250)); box-shadow: inset 1px 0 3px oklch(0 0 0 / 55%); }
.theme-skeuomorphism.alt-mode ::-webkit-scrollbar-thumb { background: linear-gradient(90deg, oklch(0.46 0.01 250), oklch(0.34 0.01 250)); border-color: oklch(0.16 0.01 250); box-shadow: inset 0 1px 0 oklch(1 0 0 / 20%); }
.theme-skeuomorphism.alt-mode .label-caps { text-shadow: 0 -1px 0 oklch(0 0 0 / 60%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
